		String suffix = paramName == null ? "" : paramName.toString();
		String setterName;
		if (suffix.length() == 0) {
			setterName = prefix;
		} else if (prefix.length() == 0) {
			setterName = suffix;
		} else {
			lombok.core.configuration.CapitalizationStrategy strategy = job.sourceNode.getAst().readConfigurationOr(ConfigurationKeys.ACCESSORS_JAVA_BEANS_SPEC_CAPITALIZATION, lombok.core.configuration.CapitalizationStrategy.defaultValue());
			char first = suffix.charAt(0);
			String capitalized;
			if (strategy == lombok.core.configuration.CapitalizationStrategy.BEANSPEC) {
				if (!Character.isLowerCase(first) || (suffix.length() > 1 && Character.isUpperCase(suffix.charAt(1)))) {
					capitalized = suffix;
				} else {
					boolean useUpperCase = suffix.length() > 2 && Character.isTitleCase(suffix.charAt(1));
					if (useUpperCase) {
						capitalized = Character.toUpperCase(first) + suffix.substring(1);
					} else {
						capitalized = Character.toTitleCase(first) + suffix.substring(1);
					}
				}
			} else {
				if (!Character.isLowerCase(first)) {
					capitalized = suffix;
				} else {
					boolean useUpperCase = suffix.length() > 2 && (Character.isTitleCase(suffix.charAt(1)) || Character.isUpperCase(suffix.charAt(1)));
					if (useUpperCase) {
						capitalized = Character.toUpperCase(first) + suffix.substring(1);
					} else {
						capitalized = Character.toTitleCase(first) + suffix.substring(1);
					}
				}
			}
			setterName = prefix + capitalized;
		}
		if (setterName == null) return;
		Name setterName_ = job.builderType.toName(setterName);

		boolean alreadyExists = false;
		if (setterName.length() > 0) {
			for (JavacNode child : job.builderType.down()) {
				if (child.getKind() == Kind.METHOD) {
					JCMethodDecl methodDecl = (JCMethodDecl) child.get();
					if (methodDecl != null) {
						Name existingName = methodDecl.name;
						if (existingName != null && existingName.equals(setterName_)) {
							boolean tolerated = false;
							if (methodDecl.getModifiers() != null) {
								List<JCAnnotation> existingAnns = methodDecl.getModifiers().getAnnotations();
								if (existingAnns != null) {
									for (JCAnnotation anno : existingAnns) {
