		for (JavacNode child : originalFieldNode.down()) {
			if (child.getKind() == Kind.ANNOTATION) {
				JCAnnotation annotation = (JCAnnotation) child.get();
				for (String copyToSetterName : HandlerUtil.COPY_TO_SETTER_ANNOTATIONS) {
					if (typeMatches(copyToSetterName, originalFieldNode, annotation.annotationType)) {
						copyToSetterBuf.append(annotation);
						break;
					}
				}
			}
		}
		List<JCAnnotation> methodAnns = copyAnnotations(copyToSetterBuf.toList());
		if (job.checkerFramework.generateReturnsReceiver()) {
			JCAnnotation rrAnnotation = maker.Annotation(genTypeRef(job.builderType, CheckerFrameworkVersion.NAME__RETURNS_RECEIVER), List.<JCExpression>nil());
			returnType = maker.AnnotatedType(List.of(rrAnnotation), returnType);
		}

		JCVariableDecl fieldDecl = (JCVariableDecl) fieldNode.get();
		if (paramName == null) paramName = fieldDecl.name;
		JCExpression receiver = null;
		if ((fieldDecl.mods.flags & Flags.STATIC) == 0) {
			receiver = maker.Ident(fieldNode.toName("this"));
		} else {
			JavacNode containerNode = fieldNode.up();
			if (containerNode != null && containerNode.get() instanceof JCClassDecl) {
				JCClassDecl container = (JCClassDecl) containerNode.get();
				receiver = maker.Ident(container.name);
			}
		}
		JCExpression fieldRef = receiver == null ? maker.Ident(fieldDecl.name) : maker.Select(receiver, fieldDecl.name);
		JCExpression assignedValue = maker.Ident(paramName);
		JCAssign assign = maker.Assign(fieldRef, assignedValue);

		List<JCAnnotation> copyableAnnotations = findCopyableAnnotations(fieldNode);
		List<JCAnnotation> copiedOnParam = copyAnnotations(annosOnParam);
		List<JCAnnotation> annsOnParam = copiedOnParam.appendList(copyableAnnotations);
		long flags = JavacHandlerUtil.addFinalIfNeeded(Flags.PARAMETER, fieldNode.getContext());
		JCExpression pType = cloneType(maker, fieldDecl.vartype, job.sourceNode);
		JCModifiers paramMods = maker.Modifiers(flags, annsOnParam);
		JCVariableDecl param = maker.VarDef(paramMods, paramName, pType, null);

		boolean hasNonNullOnField = hasNonNullAnnotations(fieldNode);
		boolean hasNonNullOnParam = hasNonNullAnnotations(fieldNode, annosOnParam);
		ListBuffer<JCStatement> statements = new ListBuffer<JCStatement>();
		if (!hasNonNullOnField && !hasNonNullOnParam) {
			statements.append(maker.Exec(assign));
		} else {
			lombok.core.configuration.NullCheckExceptionType exceptionType = job.sourceNode.getAst().readConfiguration(ConfigurationKeys.NON_NULL_EXCEPTION_TYPE);
			if (exceptionType == null) exceptionType = lombok.core.configuration.NullCheckExceptionType.NULL_POINTER_EXCEPTION;
			JCStatement nullCheck = null;
			if (fieldDecl.vartype == null || !isPrimitive(fieldDecl.vartype)) {
				String exceptionMessage = exceptionType.toExceptionMessage(paramName.toString(), null);
				JCLiteral message = maker.Literal(exceptionMessage);
				lombok.core.LombokImmutableList<String> nullCheckMethod = exceptionType.getMethod();
				if (nullCheckMethod != null) {
					JCExpression methodExpr = chainDots(job.sourceNode, nullCheckMethod);
					nullCheck = maker.Exec(maker.Apply(List.<JCExpression>nil(), methodExpr, List.of(maker.Ident(paramName), message)));
				} else if (exceptionType == lombok.core.configuration.NullCheckExceptionType.ASSERTION) {
					nullCheck = maker.Assert(maker.Binary(CTC_NOT_EQUAL, maker.Ident(paramName), maker.Literal(CTC_BOT, null)), message);
				} else {
					String exceptionTypeName = exceptionType.getExceptionType();
					JCExpression exType = genTypeRef(job.sourceNode, exceptionTypeName);
					JCExpression exception = maker.NewClass(null, List.<JCExpression>nil(), exType, List.<JCExpression>of(message), null);
					JCStatement throwStatement = maker.Throw(exception);
					JCBlock throwBlock = maker.Block(0, List.of(throwStatement));
					nullCheck = maker.If(maker.Binary(CTC_EQUAL, maker.Ident(paramName), maker.Literal(CTC_BOT, null)), throwBlock, null);
				}
			}
			if (nullCheck != null) statements.append(nullCheck);
			statements.append(maker.Exec(assign));
		}
		if (nameOfSetFlag != null) {
			JCAssign setBool = maker.Assign(maker.Ident(nameOfSetFlag), maker.Literal(CTC_BOOLEAN, 1));
			statements.append(maker.Exec(setBool));
		}
		JCExpression methodType = returnType;
		if (methodType == null) {
			methodType = maker.Type(Javac.createVoidType(fieldNode.getSymbolTable(), CTC_VOID));
			returnStatement = null;
		}
		if (returnStatement != null) statements.append(returnStatement);
		JCBlock methodBody = maker.Block(0, statements.toList());
		List<JCAnnotation> copiedMethodAnns = copyAnnotations(methodAnns);
		List<JCAnnotation> setterAnnsFromField = findCopyableToSetterAnnotations(fieldNode);
		List<JCAnnotation> annsOnMethod = mergeAnnotations(copiedMethodAnns, setterAnnsFromField);
		if (isFieldDeprecated(fieldNode) || deprecate) {
			JCAnnotation deprecatedAnn = maker.Annotation(genJavaLangTypeRef(fieldNode, "Deprecated"), List.<JCExpression>nil());
			annsOnMethod = annsOnMethod.prepend(deprecatedAnn);
		}

		AnnotationValues<Accessors> accessors = null;
		for (JavacNode node : fieldNode.down()) {
			if (annotationTypeMatches(Accessors.class, node)) {
				accessors = createAnnotation(Accessors.class, node);
				break;
			}
		}
		JavacNode current = fieldNode.up();
		while (current != null) {
			for (JavacNode node : current.down()) {
				if (annotationTypeMatches(Accessors.class, node)) {
					AnnotationValues<Accessors> onType = createAnnotation(Accessors.class, node);
					accessors = accessors == null ? onType : accessors.integrate(onType);
					break;
				}
			}
			current = current.up();
		}
		if (accessors == null) accessors = AnnotationValues.of(Accessors.class, fieldNode);
		long access = Flags.PUBLIC;
		if ((fieldDecl.mods.flags & Flags.STATIC) == 0) {
			boolean makeFinalExplicit = accessors.isExplicit("makeFinal");
			if (makeFinalExplicit) {
				if (accessors.getAsBoolean("makeFinal")) access |= Flags.FINAL;
			} else {
				Boolean makeFinalConfig = fieldNode.getAst().readConfiguration(ConfigurationKeys.ACCESSORS_MAKE_FINAL);
				if (makeFinalConfig != null && makeFinalConfig.booleanValue()) access |= Flags.FINAL;
			}
		}

		Name methodName = fieldNode.toName(setterName);
		List<JCTypeParameter> methodGenericParams = List.nil();
		List<JCVariableDecl> parameters = List.of(param);
		List<JCExpression> throwsClauses = List.nil();
		JCExpression annotationMethodDefaultValue = null;
		JCModifiers methodMods = maker.Modifiers(access, annsOnMethod);
		JCMethodDecl methodDef = maker.MethodDef(methodMods, methodName, methodType, methodGenericParams, parameters, throwsClauses, methodBody, annotationMethodDefaultValue);
		if (returnStatement != null) createRelevantNonNullAnnotation(job.sourceNode, methodDef);
		JCMethodDecl newMethod = recursiveSetGeneratedBy(methodDef, job.sourceNode);
		try {
			final JCCompilationUnit cu = (JCCompilationUnit) fieldNode.top().get();
			final JCTree sourceTree = fieldNode.get();
			String javadoc = Javac.getDocComment(cu, sourceTree);
			String section = null;
			if (javadoc != null && !javadoc.isEmpty()) {
				Pattern sectionFinder = Pattern.compile("^\\s*\\**\\s*[-*][-*]+\\s*([GS]ETTER|WITH(?:ER)?)\\s*[-*][-*]+\\s*\\**\\s*$", Pattern.MULTILINE | Pattern.CASE_INSENSITIVE);
				Pattern lineBreakFinder = Pattern.compile("(\\r?\\n)?");
				Matcher sectionMatcher = sectionFinder.matcher(javadoc);
				Matcher lineBreakMatcher = lineBreakFinder.matcher(javadoc);
				int sectionStart = -1;
				int sectionEnd = -1;
				while (sectionMatcher.find()) {
					boolean found = sectionMatcher.group(1).equalsIgnoreCase("SETTER");
					if (found) {
						lineBreakMatcher.find(sectionMatcher.end());
						sectionStart = lineBreakMatcher.end();
					} else if (sectionStart != -1) {
						sectionEnd = sectionMatcher.start();
					}
				}
				if (sectionStart != -1) {
					if (sectionEnd != -1) {
						section = javadoc.substring(sectionStart, sectionEnd);
					} else {
						section = javadoc.substring(sectionStart);
					}
				}
			}
			final boolean sectionBased = section != null;
			String out;
			if (sectionBased) {
				out = section;
			} else {
				out = stripLinesWithTagFromJavadoc(stripSectionsFromJavadoc(javadoc), JavadocTag.RETURN);
			}
			if (returnStatement != null) {
				out = addReturnsThisIfNeeded(out);
			}
			Javac.setDocComment(cu, newMethod, out);
			fieldNode.getAst().cleanupTask("javadocfilter-setter", sourceTree, new CleanupTask() {
				@Override public void cleanup() {
					String leftover = Javac.getDocComment(cu, sourceTree);
					if (leftover == null || leftover.isEmpty()) return;
					leftover = stripSectionsFromJavadoc(leftover);
					if (!sectionBased) {
						leftover = stripLinesWithTagFromJavadoc(stripSectionsFromJavadoc(leftover), JavadocTag.PARAM);
					}
					Javac.setDocComment(cu, sourceTree, leftover);
				}
			});
		} catch (Exception ignore) {}
		injectMethod(job.builderType, newMethod);
	}

	private void addObtainVia(BuilderFieldData bfd, JavacNode node) {
		for (JavacNode child : node.down()) {
			if (!annotationTypeMatches(ObtainVia.class, child)) continue;
			AnnotationValues<ObtainVia> ann = createAnnotation(ObtainVia.class, child);
			bfd.obtainVia = ann.getInstance();
			bfd.obtainViaNode = child;
			deleteAnnotationIfNeccessary(child, ObtainVia.class);
			return;
		}
	}

	/**
	 * Returns the explicitly requested singular annotation on this node (field
	 * or parameter), or null if there's no {@code @Singular} annotation on it.
	 *
	 * @param node The node (field or method param) to inspect for its name and potential {@code @Singular} annotation.
	 * @param setterPrefix the prefix for setter methods
	 */
	private SingularData getSingularData(JavacNode node, String setterPrefix) {
		for (JavacNode child : node.down()) {
			if (!annotationTypeMatches(Singular.class, child)) continue;
			Name pluralName = node.getKind() == Kind.FIELD ? removePrefixFromField(node) : ((JCVariableDecl) node.get()).name;
			AnnotationValues<Singular> ann = createAnnotation(Singular.class, child);
			Singular singularInstance = ann.getInstance();
			deleteAnnotationIfNeccessary(child, Singular.class);
			String explicitSingular = singularInstance.value();
			if (explicitSingular.isEmpty()) {
				if (Boolean.FALSE.equals(node.getAst().readConfiguration(ConfigurationKeys.SINGULAR_AUTO))) {
					node.addError("The singular must be specified explicitly (e.g. @Singular(\"task\")) because auto singularization is disabled.");
					explicitSingular = pluralName.toString();
				} else {
					explicitSingular = autoSingularize(pluralName.toString());
					if (explicitSingular == null) {
						node.addError("Can't singularize this name; please specify the singular explicitly (i.e. @Singular(\"sheep\"))");
						explicitSingular = pluralName.toString();
					}
				}
			}
			Name singularName = node.toName(explicitSingular);

			JCExpression type = null;
			if (node.get() instanceof JCVariableDecl) type = ((JCVariableDecl) node.get()).vartype;

			String name = null;
			List<JCExpression> typeArgs = List.nil();
			if (type instanceof JCTypeApply) {
				typeArgs = ((JCTypeApply) type).arguments;
				type = ((JCTypeApply) type).clazz;
			}

			name = type.toString();

			String targetFqn = JavacSingularsRecipes.get().toQualified(name);
			JavacSingularizer singularizer = JavacSingularsRecipes.get().getSingularizer(targetFqn, node);
			if (singularizer == null) {
				node.addError("Lombok does not know how to create the singular-form builder methods for type '" + name + "'; they won't be generated.");
				return null;
			}

			return new SingularData(child, singularName, pluralName, typeArgs, targetFqn, singularizer, singularInstance.ignoreNullCollections(), setterPrefix);
		}

		return null;
	}

	private java.util.HashSet<String> gatherUsedTypeNames(List<JCTypeParameter> typeParams, JCClassDecl td) {
		java.util.HashSet<String> usedNames = new HashSet<String>();

		// 1. Add type parameter names.
		for (JCTypeParameter typeParam : typeParams)
			usedNames.add(typeParam.getName().toString());

		// 2. Add class name.
		usedNames.add(td.name.toString());

		// 3. Add used type names.
		for (JCTree member : td.getMembers()) {
			if (member.getKind() == com.sun.source.tree.Tree.Kind.VARIABLE && member instanceof JCVariableDecl) {
				JCTree type = ((JCVariableDecl)member).getType();
				if (type instanceof JCIdent)
					usedNames.add(((JCIdent)type).getName().toString());
			}
		}

		// 4. Add extends and implements clauses.
		addFirstToken(usedNames, Javac.getExtendsClause(td));
		for (JCExpression impl : td.getImplementsClause()) {
			addFirstToken(usedNames, impl);
		}

		return usedNames;
	}

	private void addFirstToken(java.util.Set<String> usedNames, JCTree type) {
		if (type == null) 
			return;
		if (type instanceof JCTypeApply) {
			type = ((JCTypeApply)type).clazz;
		}
		while (type instanceof JCFieldAccess && ((JCFieldAccess)type).selected != null) {
			// Add the first token, because only that can collide.
			type = ((JCFieldAccess)type).selected;
		}
		usedNames.add(type.toString());
	}

	private String generateNonclashingNameFor(String classGenericName, java.util.HashSet<String> typeParamStrings) {
		if (!typeParamStrings.contains(classGenericName)) return classGenericName;
		int counter = 2;
		while (typeParamStrings.contains(classGenericName + counter)) counter++;
		return classGenericName + counter;
	}

	private JavacNode findInnerClass(JavacNode parent, String name) {
		for (JavacNode child : parent.down()) {
			if (child.getKind() != Kind.TYPE) continue;
			JCClassDecl td = (JCClassDecl) child.get();
			if (td.name.contentEquals(name)) return child;
		}
		return null;
	}

	private ListBuffer<JCExpression> getTypeParamExpressions(List<? extends JCTree> typeParams, JavacTreeMaker maker, JavacNode source) {
		ListBuffer<JCExpression> typeParamsForBuilderParameter = new ListBuffer<JCExpression>();
		for (JCTree typeParam : typeParams) {
			if (typeParam instanceof JCTypeParameter) {
				typeParamsForBuilderParameter.append(maker.Ident(((JCTypeParameter)typeParam).getName()));
			} else if (typeParam instanceof JCIdent) {
				typeParamsForBuilderParameter.append(maker.Ident(((JCIdent)typeParam).getName()));
			} else if (typeParam instanceof JCFieldAccess) {
				typeParamsForBuilderParameter.append(copySelect(maker, (JCFieldAccess) typeParam));
			} else if (typeParam instanceof JCTypeApply) {
				typeParamsForBuilderParameter.append(cloneType(maker, (JCTypeApply)typeParam, source));
			}
		}
		return typeParamsForBuilderParameter;
	}

	private JCExpression copySelect(JavacTreeMaker maker, JCFieldAccess typeParam) {
		java.util.List<Name> chainNames = new ArrayList<Name>();
		JCExpression expression = typeParam;
		while (expression != null) {
			if (expression instanceof JCFieldAccess) {
				chainNames.add(((JCFieldAccess) expression).getIdentifier());
				expression = ((JCFieldAccess) expression).getExpression();
			} else if (expression instanceof JCIdent) {
				chainNames.add(((JCIdent) expression).getName());
				expression = null;
			}
		}

		Collections.reverse(chainNames);
		JCExpression typeParameter = null;
		for (Name name : chainNames) {
			if (typeParameter == null) {
				typeParameter = maker.Ident(name);
			} else {
				typeParameter = maker.Select(typeParameter, name);
			}
		}
		return typeParameter;
	}

	/**
	 * Checks if there is a manual constructor in the given type with a single parameter (builder).
	 */
	private boolean constructorExists(JavacNode type, String builderClassName) {
		if (type != null && type.get() instanceof JCClassDecl) {
			for (JCTree def : ((JCClassDecl)type.get()).defs) {
				if (def instanceof JCMethodDecl) {
					JCMethodDecl md = (JCMethodDecl) def;
					String name = md.name.toString();
					boolean matches = name.equals("<init>");
					if (isTolerate(type, md)) 
						continue;
					if (matches && md.params != null && md.params.length() == 1) {
						// Cannot use typeMatches() here, because the parameter could be fully-qualified, partially-qualified, or not qualified.
						// A string-compare of the last part should work. If it's a false-positive, users could still @Tolerate it.
						String typeName = md.params.get(0).getType().toString();
						int lastIndexOfDot = typeName.lastIndexOf('.');
						if (lastIndexOfDot >= 0) {
							typeName = typeName.substring(lastIndexOfDot+1);
						}
						if ((builderClassName+"<?, ?>").equals(typeName))
							return true;
					}
				}
			}
		}
		return false;
	}
}

